BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE intake_kind AS ENUM ('quick_fix','agency_overflow','production_rescue');
CREATE TYPE lead_status AS ENUM ('new_lead','awaiting_information','awaiting_review','quote_sent','awaiting_payment','paid','in_progress','awaiting_client_acceptance','completed','rejected','refunded');
CREATE TYPE invoice_status AS ENUM ('open','paid','expired','ambiguous','manual_review');
CREATE TABLE partners(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL CHECK(slug ~ '^[a-z0-9_-]{2,64}$'),name text NOT NULL,commission_bps integer NOT NULL DEFAULT 2000 CHECK(commission_bps BETWEEN 0 AND 5000),status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),telegram_user_id bigint,telegram_username text,intake_kind intake_kind NOT NULL,status lead_status NOT NULL DEFAULT 'new_lead',attribution_source text NOT NULL DEFAULT 'direct',partner_id uuid REFERENCES partners(id),intake jsonb NOT NULL,qualification jsonb,internal_notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lead_id uuid NOT NULL REFERENCES leads(id),scope text NOT NULL,acceptance_test jsonb NOT NULL,price_minor bigint NOT NULL CHECK(price_minor>=0),currency text NOT NULL CHECK(currency IN('USDT','USDC')),network text NOT NULL CHECK(network IN('TRON_TRC20','BASE_USDC')),delivery_window text NOT NULL,exclusions jsonb NOT NULL,expires_at timestamptz NOT NULL,approved_by text,approved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quote_id uuid NOT NULL UNIQUE REFERENCES quotes(id),status invoice_status NOT NULL DEFAULT 'open',network text NOT NULL,token text NOT NULL,recipient_address text NOT NULL,token_contract text NOT NULL,amount_minor bigint NOT NULL,decimals integer NOT NULL,expires_at timestamptz NOT NULL,tx_hash text UNIQUE,paid_at timestamptz,reference_usd_minor bigint,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_assignments(tx_hash text PRIMARY KEY,invoice_id uuid NOT NULL UNIQUE REFERENCES invoices(id),network text NOT NULL,evidence jsonb NOT NULL,assigned_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lead_id uuid NOT NULL UNIQUE REFERENCES leads(id),invoice_id uuid NOT NULL UNIQUE REFERENCES invoices(id),status lead_status NOT NULL DEFAULT 'paid',scope text NOT NULL,acceptance_test jsonb NOT NULL,access_checklist jsonb NOT NULL DEFAULT '[]',proof jsonb NOT NULL DEFAULT '[]',test_results jsonb NOT NULL DEFAULT '[]',delivery_message text,deadline timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lead_id uuid REFERENCES leads(id),job_id uuid REFERENCES jobs(id),storage_key text UNIQUE NOT NULL,original_name text NOT NULL,safe_name text NOT NULL,mime text NOT NULL,size_bytes bigint NOT NULL,sha256 text NOT NULL,scan_status text NOT NULL DEFAULT 'pending',delete_after timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK((lead_id IS NOT NULL)::int+(job_id IS NOT NULL)::int=1));
CREATE TABLE demand_signals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),group_id bigint NOT NULL,message_id bigint NOT NULL,excerpt text NOT NULL,score integer NOT NULL,matched_categories jsonb NOT NULL,author_user_id bigint,retained_until timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(group_id,message_id));
CREATE TABLE group_monitors(group_id bigint PRIMARY KEY,title text NOT NULL,admin_authorised boolean NOT NULL DEFAULT false,enabled boolean NOT NULL DEFAULT false,minimum_score integer NOT NULL DEFAULT 6,quiet_hours jsonb,approved_response_mode text NOT NULL DEFAULT 'notify_only',retention_days integer NOT NULL DEFAULT 30);
CREATE TABLE referrals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),partner_id uuid NOT NULL REFERENCES partners(id),lead_id uuid NOT NULL UNIQUE REFERENCES leads(id),status text NOT NULL DEFAULT 'attributed',commission_minor bigint,manual_payout_status text NOT NULL DEFAULT 'not_eligible',fraud_flags jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log(id bigserial PRIMARY KEY,actor_type text NOT NULL,actor_id text,action text NOT NULL,entity_type text NOT NULL,entity_id text,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX leads_status_idx ON leads(status,created_at DESC); CREATE INDEX attachments_delete_idx ON attachments(delete_after); CREATE INDEX invoice_status_expiry_idx ON invoices(status,expires_at); CREATE INDEX audit_entity_idx ON audit_log(entity_type,entity_id,created_at DESC);
COMMIT;